sys_script_include.script:
var ERPSecurityUtils = Class.create();
ERPSecurityUtils.prototype = {
    initialize: function() {
        this.session = gs.getSession();
        this.userId = gs.getUserID();
        this.userName = gs.getUserName();
    },

    /**
     * University-level leadership has cross-college access
     */
    isUniversityLeadership: function() {
        return gs.hasRole('x_erp.head_dean') || 
               gs.hasRole('x_erp.dean') || 
               gs.hasRole('x_erp.university_office') ||
               gs.hasRole('admin') ||
               gs.hasRole('x_1790229_edusph_0.admin');
    },

    /**
     * Resolves and caches the user's assigned college sys_id
     */
    getUserCollege: function() {
        if (this.isUniversityLeadership()) {
            return null; // Cross-college view
        }

        var cached = this.session.getClientData('erp_user_college');
        if (cached) {
            return cached;
        }

        // Check Employee record
        var empGR = new GlideRecord('x_1790229_edusph_0_employee');
        empGR.addQuery('user', this.userId);
        empGR.addQuery('active', true);
        empGR.query();
        if (empGR.next()) {
            var cId = empGR.getValue('college');
            this.session.putClientData('erp_user_college', cId);
            this.session.putClientData('erp_user_type', 'employee');
            this.session.putClientData('erp_employee_id', empGR.getUniqueValue());
            this.session.putClientData('erp_department_id', empGR.getValue('department'));
            return cId;
        }

        // Check Student record
        var stuGR = new GlideRecord('x_1790229_edusph_0_student');
        stuGR.addQuery('user', this.userId);
        stuGR.query();
        if (stuGR.next()) {
            var cIdStu = stuGR.getValue('college');
            this.session.putClientData('erp_user_college', cIdStu);
            this.session.putClientData('erp_user_type', 'student');
            this.session.putClientData('erp_student_id', stuGR.getUniqueValue());
            this.session.putClientData('erp_section_id', stuGR.getValue('section'));
            return cIdStu;
        }

        return '';
    },

    /**
     * Validates row-level college scoping
     * Safely allows form initialization on new records
     */
    canAccessCollege: function(recordCollegeId, record) {
        if (this.isUniversityLeadership()) {
            return true;
        }
        // Allow uninserted/new record form canvas rendering
        if (record && record.isNewRecord && record.isNewRecord()) {
            return true;
        }
        if (!recordCollegeId) {
            return true; // Allow blank new form rendering until college is selected/defaulted
        }
        var userCollege = this.getUserCollege();
        if (!userCollege) {
            return false;
        }
        return (userCollege.toString() === recordCollegeId.toString());
    },

    /**
     * Validates student ownership of records
     */
    isStudentOwner: function(studentField, record) {
        if (this.isUniversityLeadership()) return true;
        if (record && record.isNewRecord && record.isNewRecord()) return true;
        if (!studentField) return true;
        var sId = (typeof studentField === 'object' && studentField != null) ? studentField.toString() : studentField;
        var myStuId = this.session.getClientData('erp_student_id');
        if (!myStuId) {
            this.getUserCollege();
            myStuId = this.session.getClientData('erp_student_id');
        }
        return (myStuId && myStuId.toString() === sId.toString());
    },

    /**
     * Validates faculty ownership of records
     */
    isFacultyOwner: function(facultyField, record) {
        if (this.isUniversityLeadership()) return true;
        if (record && record.isNewRecord && record.isNewRecord()) return true;
        if (!facultyField) return true;
        var fId = (typeof facultyField === 'object' && facultyField != null) ? facultyField.toString() : facultyField;
        var myEmpId = this.session.getClientData('erp_employee_id');
        if (!myEmpId) {
            this.getUserCollege();
            myEmpId = this.session.getClientData('erp_employee_id');
        }
        return (myEmpId && myEmpId.toString() === fId.toString());
    },

    /**
     * Validates applicant ownership of admission application
     */
    isApplicantOwner: function(createdByUser, record) {
        if (this.isUniversityLeadership()) return true;
        if (record && record.isNewRecord && record.isNewRecord()) return true;
        if (!createdByUser) return true;
        return (createdByUser.toString() === this.userName.toString());
    },

    /**
     * Fallback routing: if approver is missing/unassigned, falls back to Director
     */
    getApprovalFallback: function(collegeId) {
        var colGR = new GlideRecord('x_1790229_edusph_0_college');
        if (colGR.get(collegeId)) {
            return colGR.getValue('director');
        }
        return null;
    },

    type: 'ERPSecurityUtils'
};
